SELECT L.IP, L.URITYPE, L.URL, L.URI, L.PARAM, REPLACE(REPLACE(L.DATA,'↓',':'),'↑',':') AS DATA, L.CREATEUSER, L.CREATEDATE, MM.MENUID, (CASE WHEN (CL.LABEL IS NULL OR CL.LABEL = '') THEN MM.MENUNAME ELSE CL.LABEL END) AS LBLTXL, MU.USERNAME FROM SYSLOG L LEFT OUTER JOIN MSTMENU MM ON MM.URI = L.URI LEFT OUTER JOIN SYSLABEL CL ON CL.LABELGID = 'MENU' AND CL.LANGCODE = #{LANGKY} AND MM.MENULABEL = CL.LABELID LEFT OUTER JOIN MSTUSER MU ON L.CREATEUSER = MU.USERID WHERE 1=1
AND TO_CHAR(L.CREATEDATE, 'YYYYMMDD') = #{CREATEDATE}
AND L.URI LIKE '%/login.data'
AND L.URI LIKE '%/logout.page'
AND (L.URITYPE = 'jsp' OR L.URITYPE = 'page')
AND L.URITYPE = 'data'
AND L.URI = #{URI}
AND L.CREATEUSER = #{CREATEUSER}
ORDER BY L.CREATEDATE DESC

